  "description": "CLI and runtime for OpenPets - AI plugin infrastructure",
  "main": "./dist/src/core/index.js",
  "types": "./dist/src/core/index.d.ts",
  "bin": {
    "pets": "dist/src/core/cli.js",
    "pets-mcp": "dist/src/core/mcp-server.js"
